/// <summary>
/// <c>sky</c> layer: A spherical dome around the map that is always rendered behind all other layers.
/// </summary>
/// <remarks>
/// <b>Mapbox GL JS only.</b>
/// </remarks>
public sealed partial class SkyLayer : Layer
{
    /// <summary>
    /// The style-specification type name: <c>sky</c>.
    /// </summary>
    public const string TypeName = "sky";

    /// <summary>
    /// Creates a <c>sky</c> layer.
    /// </summary>
    /// <param name="id">Unique layer id.</param>
    public SkyLayer(string id) : base(id, TypeName) { }

    /// <summary>
    /// The type of the sky
    /// </summary>
    /// <remarks>
    /// <b>Mapbox GL JS only.</b>
    /// Requires Mapbox GL JS 2.0.0+.
    /// Default: <c>"atmosphere"</c>. Supports zoom expressions.
    /// </remarks>
    public EnumValue<SkyType>? SkyType
    {
        get => PaintProperties.TryGetValue("sky-type", out var v) ? v as EnumValue<SkyType> : null;
        set => StyleValueHelper.SetOrRemove(PaintProperties, "sky-type", value);
    }

    /// <summary>
    /// Position of the sun center [a azimuthal angle, p polar angle]. The azimuthal angle indicates the position of the sun relative to 0° north, where degrees proceed clockwise. The polar angle indicates the height of the sun, where 0° is directly above, at zenith, and 90° at the horizon. When this property is ommitted, the sun center is directly inherited from the light position.
    /// </summary>
    /// <remarks>
    /// <b>Mapbox GL JS only.</b>
    /// Requires Mapbox GL JS 2.0.0+.
    /// Range: [0, 0] to [360, 180]. Units: degrees. Supports zoom expressions.
    /// </remarks>
    public NumberArrayValue? SkyAtmosphereSun
    {
        get => PaintProperties.TryGetValue("sky-atmosphere-sun", out var v) ? v as NumberArrayValue : null;
        set => StyleValueHelper.SetOrRemove(PaintProperties, "sky-atmosphere-sun", value);
    }

    /// <summary>
    /// Intensity of the sun as a light source in the atmosphere (on a scale from 0 to a 100). Setting higher values will brighten up the sky.
    /// </summary>
    /// <remarks>
    /// <b>Mapbox GL JS only.</b>
    /// Requires Mapbox GL JS 2.0.0+.
    /// Default: <c>10</c>. Range: 0 to 100.
    /// </remarks>
    public NumberValue? SkyAtmosphereSunIntensity
    {
        get => PaintProperties.TryGetValue("sky-atmosphere-sun-intensity", out var v) ? v as NumberValue : null;
        set => StyleValueHelper.SetOrRemove(PaintProperties, "sky-atmosphere-sun-intensity", value);
    }

    /// <summary>
    /// Position of the gradient center [a azimuthal angle, p polar angle]. The azimuthal angle indicates the position of the gradient center relative to 0° north, where degrees proceed clockwise. The polar angle indicates the height of the gradient center, where 0° is directly above, at zenith, and 90° at the horizon.
    /// </summary>
    /// <remarks>
    /// <b>Mapbox GL JS only.</b>
    /// Requires Mapbox GL JS 2.0.0+.
    /// Default: <c>[0, 0]</c>. Range: [0, 0] to [360, 180]. Units: degrees. Supports zoom expressions.
    /// </remarks>
    public NumberArrayValue? SkyGradientCenter
    {
        get => PaintProperties.TryGetValue("sky-gradient-center", out var v) ? v as NumberArrayValue : null;
        set => StyleValueHelper.SetOrRemove(PaintProperties, "sky-gradient-center", value);
    }

    /// <summary>
    /// The angular distance from <c>sky-gradient-center</c> up to which the gradient extends. A value of 180 causes the gradient to wrap around to the opposite direction from <c>sky-gradient-center</c>.
    /// </summary>
    /// <remarks>
    /// <b>Mapbox GL JS only.</b>
    /// Requires Mapbox GL JS 2.0.0+.
    /// Default: <c>90</c>. Range: 0 to 180. Units: degrees. Supports zoom expressions.
    /// </remarks>
    public NumberValue? SkyGradientRadius
    {
        get => PaintProperties.TryGetValue("sky-gradient-radius", out var v) ? v as NumberValue : null;
        set => StyleValueHelper.SetOrRemove(PaintProperties, "sky-gradient-radius", value);
    }

    /// <summary>
    /// Defines a radial color gradient with which to color the sky. The color values can be interpolated with an expression using <c>sky-radial-progress</c>. The range [0, 1] for the interpolant covers a radial distance (in degrees) of [0, <c>sky-gradient-radius</c>] centered at the position specified by <c>sky-gradient-center</c>.
    /// </summary>
    /// <remarks>
    /// <b>Mapbox GL JS only.</b>
    /// Requires Mapbox GL JS 2.0.0+.
    /// Default: <c>["interpolate", ["linear"], ["sky-radial-progress"], 0.8, "#87ceeb", 1, "white"]</c>.
    /// </remarks>
    public ColorValue? SkyGradient
    {
        get => PaintProperties.TryGetValue("sky-gradient", out var v) ? v as ColorValue : null;
        set => StyleValueHelper.SetOrRemove(PaintProperties, "sky-gradient", value);
    }

    /// <summary>
    /// A color applied to the atmosphere sun halo. The alpha channel describes how strongly the sun halo is represented in an atmosphere sky layer.
    /// </summary>
    /// <remarks>
    /// <b>Mapbox GL JS only.</b>
    /// Requires Mapbox GL JS 2.0.0+.
    /// Default: <c>"white"</c>.
    /// </remarks>
    public ColorValue? SkyAtmosphereHaloColor
    {
        get => PaintProperties.TryGetValue("sky-atmosphere-halo-color", out var v) ? v as ColorValue : null;
        set => StyleValueHelper.SetOrRemove(PaintProperties, "sky-atmosphere-halo-color", value);
    }

    /// <summary>
    /// A color used to tweak the main atmospheric scattering coefficients. Using white applies the default coefficients giving the natural blue color to the atmosphere. This color affects how heavily the corresponding wavelength is represented during scattering. The alpha channel describes the density of the atmosphere, with 1 maximum density and 0 no density.
    /// </summary>
    /// <remarks>
    /// <b>Mapbox GL JS only.</b>
    /// Requires Mapbox GL JS 2.0.0+.
    /// Default: <c>"white"</c>.
    /// </remarks>
    public ColorValue? SkyAtmosphereColor
    {
        get => PaintProperties.TryGetValue("sky-atmosphere-color", out var v) ? v as ColorValue : null;
        set => StyleValueHelper.SetOrRemove(PaintProperties, "sky-atmosphere-color", value);
    }

    /// <summary>
    /// The opacity of the entire sky layer.
    /// </summary>
    /// <remarks>
    /// <b>Mapbox GL JS only.</b>
    /// Requires Mapbox GL JS 2.0.0+.
    /// Default: <c>1</c>. Range: 0 to 1. Supports zoom expressions.
    /// </remarks>
    public NumberValue? SkyOpacity
    {
        get => PaintProperties.TryGetValue("sky-opacity", out var v) ? v as NumberValue : null;
        set => StyleValueHelper.SetOrRemove(PaintProperties, "sky-opacity", value);
    }

    /// <summary>
    /// Transition applied when <see cref="SkyOpacity"/> changes.
    /// </summary>
    public StyleTransition? SkyOpacityTransition
    {
        get => PaintProperties.TryGetValue("sky-opacity-transition", out var v) ? v as StyleTransition : null;
        set => StyleValueHelper.SetOrRemove(PaintProperties, "sky-opacity-transition", value);
    }

}

