public abstract partial class Layer
{
    /// <summary>
    /// Creates an empty layer instance of the given style type (unknown types give a <see cref="RawLayer"/>).
    /// </summary>
    public static Layer CreateOfType(string type, string id) => type switch
    {
        "fill" => new FillLayer(id),
        "line" => new LineLayer(id),
        "symbol" => new SymbolLayer(id),
        "circle" => new CircleLayer(id),
        "heatmap" => new HeatmapLayer(id),
        "fill-extrusion" => new FillExtrusionLayer(id),
        "raster" => new RasterLayer(id),
        "raster-particle" => new RasterParticleLayer(id),
        "hillshade" => new HillshadeLayer(id),
        "model" => new ModelLayer(id),
        "background" => new BackgroundLayer(id),
        "sky" => new SkyLayer(id),
        "slot" => new SlotLayer(id),
        "clip" => new ClipLayer(id),
        "color-relief" => new ColorReliefLayer(id),
        _ => new RawLayer(id, type),
    };
}
